edits.before:
if (event.key === ESCAPE_KEY) {
  const button = this.matches(SELECTOR_DATA_TOGGLE) ? this : SelectorEngine.prev(this, SELECTOR_DATA_TOGGLE)[0]
  button.focus()
  Dropdown.clearMenus()
  return
}

edits.after:
if (event.key === ESCAPE_KEY) {
  const button = this.matches(SELECTOR_DATA_TOGGLE) ? this : SelectorEngine.prev(this, SELECTOR_DATA_TOGGLE)[0]
  button.focus()
  Dropdown.clearMenus()
  if (isActive) {
    event.stopPropagation()
  }
  return
}
